import sys; sys.path.insert(0,'/tmp/claude-0/-home-user-acompagnement/add46904-4241-51c5-837a-9d7b561d32e5/scratchpad/scripts')
from ebook_common import *
T='Recettes du soir pour mieux dormir'
P=[]
P.append(cover2('15','15 recettes · maison','Recettes du soir<br><em>pour mieux dormir</em>','Boissons, dîners légers, collations et desserts : des recettes simples et gourmandes pour préparer des nuits plus douces.','Guide offert'))
P.append(f'''<div class="page"><div class="kicker">Introduction</div><h2>Ce que tu manges <em>se ressent la nuit</em></h2><div class="rule"></div>
<p class="lead">Aucun aliment n'est un somnifère. Mais le contenu de ton assiette, et surtout l'heure à laquelle tu dînes, peuvent faciliter ou perturber ton sommeil.</p>
<div class="grid2" style="margin-top:12px">
<div class="box"><h3 style="margin-top:0">À privilégier le soir</h3><ul class="ch">
<li><b>Les féculents complets</b> (riz complet, quinoa, patate douce, flocons d'avoine) : ils rassasient sans alourdir.</li>
<li><b>Les aliments sources de tryptophane</b>, l'acide aminé précurseur de la mélatonine : volaille, œufs, produits laitiers, légumineuses, graines de courge.</li>
<li><b>Les aliments riches en magnésium</b> : amandes, épinards, banane, chocolat noir, légumineuses. Le magnésium contribue au fonctionnement normal du système nerveux.</li>
<li><b>La cerise griotte</b> : l'une des rares sources naturelles de mélatonine dans l'alimentation.</li></ul></div>
<div class="box line"><h3 style="margin-top:0">À limiter</h3><ul class="ch">
<li><b>La caféine après 14 h</b> : café, thé, cola, boissons énergisantes.</li>
<li><b>L'alcool</b> : il aide parfois à s'endormir, mais fragmente la deuxième partie de la nuit.</li>
<li><b>Les plats gras, épicés ou très copieux</b> : la digestion lourde perturbe l'endormissement.</li>
<li><b>Le dîner tardif</b> : idéalement, termine ton repas 2 à 3 heures avant le coucher.</li>
<li><b>Trop boire juste avant le lit</b> : pour éviter les réveils pour aller aux toilettes.</li></ul></div></div>
<h3>Sommaire</h3>
<div class="toc"><a><span>Boissons du soir</span><span>3</span></a><a><span>Dîners légers</span><span>5</span></a><a><span>Collations du soir</span><span>7</span></a><a><span>Desserts doux</span><span>9</span></a><a><span>Ton menu de la semaine</span><span>10</span></a><a><span>Liste de courses</span><span>11</span></a></div>
{foot(T,2)}</div>''')
def rec(name, meta, ings, steps, why):
    return f'''<div class="recipe"><div><h3>{name}</h3><div class="meta">{''.join(f"<span>{m}</span>" for m in meta)}</div><b style="font-size:9pt">Ingrédients</b><ul>{''.join(f"<li>{i}</li>" for i in ings)}</ul></div>
<div><b style="font-size:9pt">Préparation</b><ol>{''.join(f"<li>{s}</li>" for s in steps)}</ol><p class="why">{why}</p></div></div>'''
R={}
R['b1']=rec('Lait d\'or apaisant',['5 min','1 tasse','Sans gluten'],['250 ml de lait (ou boisson végétale amande / avoine)','½ c. à café de curcuma','1 pincée de cannelle','1 pincée de poivre noir','1 fine tranche de gingembre frais','1 c. à café de miel'],['Fais chauffer doucement le lait avec le curcuma, la cannelle, le poivre et le gingembre, sans faire bouillir.','Laisse infuser 3 minutes hors du feu.','Filtre, ajoute le miel et déguste bien chaud.'],'Un rituel chaud et sans caféine, idéal pour marquer la fin de la journée.')
R['b2']=rec('Infusion camomille, tilleul & miel',['5 min','1 tasse','Vegan sans le miel'],['1 c. à café de camomille séchée','1 c. à café de tilleul séché','250 ml d\'eau frémissante','1 c. à café de miel','1 zeste d\'orange (facultatif)'],['Verse l\'eau frémissante sur les plantes.','Couvre et laisse infuser 5 à 7 minutes.','Filtre, ajoute le miel et le zeste.'],'La camomille et le tilleul sont des plantes traditionnellement utilisées le soir pour un moment de détente.')
R['b3']=rec('Mocktail griotte & verveine',['5 min','1 verre','Sans alcool'],['5 cl de jus de cerise griotte pur (sans sucre ajouté)','15 cl d\'infusion de verveine refroidie','Quelques griottes (fraîches ou surgelées)','1 brin de menthe'],['Prépare l\'infusion de verveine et laisse-la tiédir.','Mélange avec le jus de griotte dans un verre.','Ajoute les griottes et la menthe.'],'Une alternative douce au verre de vin du soir. À boire en début de soirée plutôt que juste avant le coucher.')
R['b4']=rec('Lait chaud amande-cannelle',['5 min','1 tasse','Vegan'],['250 ml de boisson d\'amande','1 c. à soupe de purée d\'amande','½ c. à café de cannelle','½ c. à café d\'extrait de vanille','1 c. à café de sirop d\'érable'],['Fouette tous les ingrédients dans une casserole.','Chauffe à feu doux 3 à 4 minutes en remuant.','Saupoudre d\'un peu de cannelle et sers.'],'Doux et réconfortant ; l\'amande est une source de magnésium.')
R['d1']=rec('Velouté de courge & lentilles corail',['30 min','4 pers.','Vegan'],['600 g de courge butternut','100 g de lentilles corail','1 oignon','1 c. à café de cumin','80 cl de bouillon de légumes','10 cl de lait de coco','Graines de courge pour servir'],['Fais revenir l\'oignon émincé avec le cumin.','Ajoute la courge en cubes, les lentilles rincées et le bouillon.','Laisse cuire 20 minutes, puis mixe avec le lait de coco.','Sers parsemé de graines de courge.'],'Léger et rassasiant : lentilles et graines de courge apportent protéines végétales et tryptophane.')
R['d2']=rec('Saumon, patate douce & épinards',['25 min','2 pers.','Sans gluten'],['2 pavés de saumon','1 grosse patate douce','2 poignées de jeunes pousses d\'épinards','1 c. à soupe d\'huile d\'olive','Jus d\'½ citron','Sel, poivre, aneth'],['Coupe la patate douce en cubes et rôtis-la 20 minutes à 200 °C avec l\'huile.','Pendant ce temps, cuis le saumon 4 minutes de chaque côté à la poêle.','Fais tomber les épinards 1 minute dans la poêle.','Assemble, arrose de citron et parsème d\'aneth.'],'Un dîner complet et digeste : poisson, féculent complet et légumes verts.')
R['d3']=rec('Bol quinoa, poulet & avocat',['20 min','2 pers.'],['120 g de quinoa','2 blancs de poulet','1 avocat','1 concombre','1 poignée de graines de sésame','Sauce : yaourt nature, citron, ciboulette'],['Cuis le quinoa 12 minutes dans l\'eau bouillante.','Fais dorer le poulet en lanières.','Dispose quinoa, poulet, avocat et concombre dans un bol.','Nappe de sauce au yaourt et parsème de sésame.'],'La volaille est une bonne source de tryptophane, le quinoa un féculent complet qui cale sans alourdir.')
R['d4']=rec('Soupe miso, tofu & légumes',['15 min','2 pers.','Vegan'],['1 l d\'eau','2 c. à soupe de pâte miso','150 g de tofu ferme','1 poignée de champignons','1 poignée d\'épinards','2 oignons nouveaux','50 g de nouilles de riz'],['Fais chauffer l\'eau sans bouillir et délaie le miso.','Ajoute les champignons émincés et les nouilles, laisse cuire 4 minutes.','Ajoute le tofu en dés et les épinards 1 minute.','Sers avec les oignons nouveaux ciselés.'],'Une soupe chaude et légère, parfaite pour les soirs où l\'on n\'a pas très faim.')
R['c1']=rec('Overnight oats à la griotte',['5 min + 1 nuit','1 pers.'],['40 g de flocons d\'avoine','12 cl de lait ou boisson végétale','1 yaourt nature','1 poignée de griottes (fraîches ou surgelées)','1 c. à café de graines de chia','1 c. à café de miel'],['Mélange flocons, lait, yaourt, chia et miel dans un bocal.','Ajoute les griottes sur le dessus.','Laisse au frais une nuit.'],'À préparer le soir pour un petit-déjeuner tout prêt… ou une petite portion en collation en début de soirée.')
R['c2']=rec('Banane & purée d\'amande',['2 min','1 pers.','Vegan'],['1 banane','1 c. à soupe de purée d\'amande','1 pincée de cannelle'],['Coupe la banane en rondelles.','Nappe de purée d\'amande et saupoudre de cannelle.'],'La collation anti-fringale du soir : banane et amande apportent du magnésium.')
R['c3']=rec('Yaourt, noix & miel',['2 min','1 pers.'],['1 yaourt nature ou skyr','1 poignée de noix','1 c. à café de miel','Quelques griottes'],['Verse le yaourt dans un bol.','Ajoute les noix concassées, le miel et les griottes.'],'Les produits laitiers sont une source de tryptophane. Une collation simple, à prendre au moins 1 heure avant le coucher.')
R['c4']=rec('Deux kiwis',['1 min','1 pers.'],['2 kiwis bien mûrs'],['Coupe les kiwis en deux et déguste-les à la cuillère, environ 1 heure avant le coucher.'],'Le kiwi du soir est une habitude populaire chez celles et ceux qui cherchent à mieux dormir : facile, frais et peu calorique.')
R['s1']=rec('Clafoutis léger aux griottes',['45 min','6 pers.'],['400 g de griottes dénoyautées','3 œufs','60 g de farine','50 g de sucre','30 cl de lait','1 c. à café de vanille','1 noisette de beurre pour le moule'],['Préchauffe le four à 180 °C et beurre un moule.','Fouette les œufs et le sucre, ajoute la farine, puis le lait et la vanille.','Répartis les griottes dans le moule et verse la pâte.','Enfourne 35 minutes. Sers tiède.'],'Le dessert signature Nasely : gourmand, peu sucré, et plein de griottes.')
R['s2']=rec('Compote pomme-cannelle',['20 min','4 pers.','Vegan'],['4 pommes','1 c. à café de cannelle','1 c. à café de vanille','5 cl d\'eau'],['Épluche et coupe les pommes en morceaux.','Fais-les cuire à couvert 15 minutes avec l\'eau, la cannelle et la vanille.','Écrase à la fourchette ou mixe.'],'Douce et digeste, à servir tiède en fin de dîner.')
R['s3']=rec('Carrés chocolat noir & amandes',['10 min + 1 h','8 carrés','Vegan'],['100 g de chocolat noir (70 % minimum)','40 g d\'amandes concassées','1 pincée de fleur de sel'],['Fais fondre le chocolat au bain-marie.','Étale-le sur une plaque recouverte de papier cuisson.','Parsème d\'amandes et de fleur de sel, puis laisse durcir au frais.'],'Le chocolat noir contient un peu de caféine : à garder pour le dîner plutôt que pour juste avant le coucher, 1 ou 2 carrés.')
P.append(f'''<div class="page"><div class="kicker">Boissons du soir</div><h2>Des tasses <em>qui apaisent</em></h2><div class="rule"></div>{R['b1']}{R['b2']}{foot(T,3)}</div>''')
P.append(f'''<div class="page"><div class="kicker">Boissons du soir</div><h2>Des tasses <em>qui apaisent</em></h2><div class="rule"></div>{R['b3']}{R['b4']}{foot(T,4)}</div>''')
P.append(f'''<div class="page"><div class="kicker">Dîners légers</div><h2>Bien dîner <em>pour bien dormir</em></h2><div class="rule"></div>{R['d1']}{R['d2']}{foot(T,5)}</div>''')
P.append(f'''<div class="page"><div class="kicker">Dîners légers</div><h2>Bien dîner <em>pour bien dormir</em></h2><div class="rule"></div>{R['d3']}{R['d4']}{foot(T,6)}</div>''')
P.append(f'''<div class="page"><div class="kicker">Collations du soir</div><h2>Une petite faim <em>avant le coucher</em> ?</h2><div class="rule"></div>{R['c1']}{R['c2']}{foot(T,7)}</div>''')
P.append(f'''<div class="page"><div class="kicker">Collations du soir</div><h2>Une petite faim <em>avant le coucher</em> ?</h2><div class="rule"></div>{R['c3']}{R['c4']}{foot(T,8)}</div>''')
P.append(f'''<div class="page"><div class="kicker">Desserts doux</div><h2>Finir le repas <em>en douceur</em></h2><div class="rule"></div>{R['s1']}{R['s2']}{R['s3']}{foot(T,9)}</div>''')
menu=[('Lundi','Velouté courge & lentilles','Infusion camomille-tilleul'),('Mardi','Saumon, patate douce & épinards','Compote pomme-cannelle'),('Mercredi','Bol quinoa, poulet & avocat','Lait d\'or'),('Jeudi','Soupe miso, tofu & légumes','Yaourt, noix & miel'),('Vendredi','Saumon, patate douce & épinards','Mocktail griotte & verveine'),('Samedi','Velouté courge & lentilles','Clafoutis aux griottes'),('Dimanche','Bol quinoa, poulet & avocat','Lait chaud amande-cannelle')]
rows=''.join(f'<tr><td style="height:12mm">{d}</td><td style="color:#1a1a1a;text-align:left;padding-left:8px">{a}</td><td style="color:#1a1a1a;text-align:left;padding-left:8px">{b}</td></tr>' for d,a,b in menu)
P.append(f'''<div class="page"><div class="kicker">Organisation</div><h2>Ton menu <em>de la semaine</em></h2><div class="rule"></div>
<p>Un exemple pour démarrer, à adapter à tes goûts. Garde le principe : un dîner léger 2 à 3 heures avant le coucher, puis une boisson chaude ou une petite douceur.</p>
<table><tr><th style="width:22%">Jour</th><th>Dîner</th><th>Douceur du soir</th></tr>{rows}</table>
<div class="box" style="margin-top:16px"><b>Astuce :</b> prépare le velouté et le quinoa en double quantité le dimanche. Tu gagneras du temps toute la semaine, et tu dîneras plus tôt.</div>
{foot(T,10)}</div>''')
shop=[('Fruits & légumes',['Courge butternut','Patate douce','Épinards (jeunes pousses)','Champignons','Oignons, oignons nouveaux','Concombre, avocat','Bananes, kiwis, pommes','Citrons, orange','Gingembre frais','Griottes (fraîches ou surgelées)']),('Protéines',['Pavés de saumon','Blancs de poulet','Tofu ferme','Œufs','Yaourts nature / skyr']),('Épicerie',['Lentilles corail','Quinoa, nouilles de riz','Flocons d\'avoine','Farine, sucre','Pâte miso, bouillon de légumes','Lait de coco','Chocolat noir 70 %']),('Graines & fruits secs',['Amandes, noix','Graines de courge','Graines de chia, sésame','Purée d\'amande']),('Tisanes & boissons',['Camomille, tilleul, verveine','Jus de griotte pur','Lait ou boisson végétale']),('Épices & douceurs',['Curcuma, cannelle, cumin','Vanille, poivre','Miel, sirop d\'érable'])]
blocks=''.join(f'<div class="card"><h3 style="margin-top:0;color:var(--ch)">{t}</h3><ul class="ch" style="font-size:9.4pt">{"".join(f"<li>{i}</li>" for i in items)}</ul></div>' for t,items in shop)
P.append(f'''<div class="page"><div class="kicker">Pratique</div><h2>Ta liste <em>de courses</em></h2><div class="rule"></div><div class="grid3">{blocks}</div>{foot(T,11)}</div>''')
P.append(back2('Bon appétit, <em>et belles nuits</em>.','Associe ces recettes au programme « Mieux dormir en 14 jours » pour de meilleurs résultats.',"Ces recettes sont proposées à titre informatif dans le cadre d'une alimentation variée et équilibrée. En cas d'allergie, de régime particulier ou de traitement en cours, demande conseil à un professionnel de santé. Nasely est un complément alimentaire : il ne remplace pas une alimentation variée et équilibrée ni un mode de vie sain. © Nasely. Reproduction interdite."))
open(sys.argv[1],'w').write(doc('Recettes du soir pour mieux dormir · Nasely',P))
